using SilentScan.Core.Predicates;
using SilentScan.Core.Reporting.Sarif;
using SilentScan.Core.Rules;

namespace SilentScan.Core.Reporting;

/// <summary>
/// One row per rule this tool can produce (docs/detection-checklist.md's "Machine-readable rule
/// catalog" item) - single source of truth for id/rationale/fix-guidance/example, feeding both
/// SARIF's `rules` block (SarifRuleCatalog projects this) and the generated docs/rules.html page.
/// Confidence-suffixed SARIF rule id variants (medium-confidence/low-confidence) are generated
/// mechanically from these base entries elsewhere (SarifRuleCatalog.RuleId) - not duplicated here.
/// </summary>
public sealed record RuleDefinition(string Id, string Rationale, string? FixGuidance = null, IReadOnlyList<string>? ExampleFixturePaths = null)
{
    /// <summary>The rule's own fixture paths, or an empty list for a rule the catalog carries no example for - never null, so a page renderer never has to null-check before iterating.</summary>
    public IReadOnlyList<string> Examples => ExampleFixturePaths ?? [];
}

public static class RuleCatalog
{
 public static IReadOnlyList<RuleDefinition> BaseRules { get; } =
 [
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.FunctionWrappedColumn), "A column is wrapped in a function call inside a predicate, preventing an index seek.", null, ["tests/SilentScan.Tests/fixtures/tier1/FUNCTION_WRAPPED_COLUMN_fires.sql", "tests/SilentScan.Tests/fixtures/tier1/FUNCTION_WRAPPED_COLUMN_isnull_fires.sql", "tests/SilentScan.Tests/fixtures/tier1/FUNCTION_WRAPPED_COLUMN_case_when_test_fires.sql", "tests/SilentScan.Tests/fixtures/tier1/FUNCTION_WRAPPED_COLUMN_json_value_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.CastOrConvertOnColumn), "A column has CAST/CONVERT applied to it inside a predicate.", null, ["tests/SilentScan.Tests/fixtures/tier1/CAST_CONVERT_ON_COLUMN_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.ColumnArithmetic), "A column has arithmetic applied to it inside a predicate.", null, ["tests/SilentScan.Tests/fixtures/tier1/COLUMN_ARITHMETIC_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.LeadingWildcardLike), "A LIKE predicate on a column starts with a wildcard, forcing a full scan.", null, ["tests/SilentScan.Tests/fixtures/tier1/LEADING_WILDCARD_LIKE_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.LikePatternNotLiteral), "A LIKE predicate's pattern is not a literal, so a leading wildcard can't be ruled out statically.", null, ["tests/SilentScan.Tests/fixtures/tier1/LIKE_PATTERN_NOT_LITERAL_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.CaseFoldOnColumn), "UPPER/LOWER wraps a column inside a predicate, forcing a scan under any collation - remediation differs by whether the column's real collation is case-sensitive.", "If the column's collation is already case-insensitive, delete the UPPER/LOWER wrap entirely - it changes nothing about which rows match. If the collation is case-sensitive, rewrite via an indexed computed column or apply a case-insensitive COLLATE to the literal instead of wrapping the column.", ["tests/SilentScan.Tests/fixtures/tier1/CASE_FOLD_ON_COLUMN_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.DateFunctionOnColumn), "A date-part function (YEAR/MONTH/DAY/DATEPART/DATEDIFF/DATEADD/DATENAME) wraps a column inside a predicate, forcing a scan - a sargable rewrite (a literal date range instead) usually restores the seek.", "Rewrite the predicate as a literal date-range comparison instead of wrapping the column in a date-part function.", ["tests/SilentScan.Tests/fixtures/tier1/DATE_YEAR_ON_COLUMN_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.Tier1RuleId(SargabilityFindingKind.CharindexOrLeftOnColumn), "CHARINDEX(x, col) or LEFT(col, n) wraps a column inside a predicate - a prefix-match shape (CHARINDEX(...) = 1, or LEFT(col, n) = 'x' with LEN('x') = n) is exactly rewritable to col LIKE 'x%'; any other shape is a genuine substring search with no sargable rewrite.", "For a prefix-match shape (CHARINDEX(x, col) = 1, or LEFT(col, n) = 'x' with LEN('x') = n), rewrite as col LIKE 'x%' to restore the seek; a genuine substring search has no sargable rewrite.", ["tests/SilentScan.Tests/fixtures/tier1/CHARINDEX_PREFIX_MATCH_fires.sql", "tests/SilentScan.Tests/fixtures/tier1/CHARINDEX_SUBSTRING_fires.sql", "tests/SilentScan.Tests/fixtures/tier1/LEFT_PREFIX_MATCH_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.VerdictRuleId(Verdict.ScanForced), "An implicit type conversion on the column side forces a full scan.", "Match the literal/parameter's type (and collation) to the column's declared type so the conversion applies to the value side instead of the column."),
 new RuleDefinition(SarifRuleCatalog.VerdictRuleId(Verdict.RangeSeek), "An implicit type conversion on the column side permits only a dynamic range seek, not a direct seek.", "Match the literal/parameter's type (and collation) to the column's declared type so the conversion applies to the value side instead of the column."),
 new RuleDefinition(SarifRuleCatalog.VerdictRuleId(Verdict.Unknown), "A predicate's sargability could not be determined (e.g. unresolved collation) - never guessed."),
 new RuleDefinition(SarifRuleCatalog.VerdictRuleId(Verdict.SeekPreserved), "A predicate compares types where the seek is preserved (reported for completeness; not filtered into ScanReportBuilder's actionable findings)."),
 new RuleDefinition(SarifRuleCatalog.VerdictRuleId(Verdict.OperandClash), "The oracle-probed type matrix confirms this exact type pair does not compile as a comparison at all - a definitive fact, not an absence of probe data."),
 new RuleDefinition(SarifRuleCatalog.DynamicSqlAnalyzedRuleId, "A dynamic SQL call site with a provably-constant argument; its contents were reparsed and analyzed like static SQL."),
 new RuleDefinition(SarifRuleCatalog.DynamicSqlUnanalyzableRuleId, "A dynamic SQL call site whose argument depends on a variable, parameter, or expression and could not be statically analyzed."),
 new RuleDefinition(SarifRuleCatalog.DynamicSqlInnerParseFailedRuleId, "A dynamic SQL call site's argument was provably constant but its reassembled text did not parse as T-SQL."),
 new RuleDefinition(SarifRuleCatalog.DynamicSqlPartiallyAnalyzedRuleId, "A dynamic SQL call site's argument contained a value standing for a whole optional clause/fragment, not a single scalar; the surrounding, unaffected query structure was analyzed, but the elided fragment's own content was never examined."),
 new RuleDefinition(SarifRuleCatalog.ExpressionDerivedRuleId, "A predicate compares a column that is a CAST/CONVERT or other computed expression by the time it reaches this statement (introduced in this statement's own derived table, or upstream in a view/TVF's SELECT list) - no index seek is possible regardless of the comparison's types."),
 new RuleDefinition(SarifRuleCatalog.CollationConflictRuleId, "Two columns with genuinely different, incompatible collations are compared directly - this does not compile (SQL Server error 468, \"Cannot resolve the collation conflict\"), not a seek/scan question."),
 new RuleDefinition(SarifRuleCatalog.WriteLossUnicodeReplacementRuleId, "An INSERT/UPDATE or SET variable assignment assigns a Unicode (NVARCHAR/NCHAR) value to a non-Unicode (VARCHAR/CHAR) target - any character outside the target collation's codepage is silently replaced with '?', with no error.", "Make the target column NVARCHAR/NCHAR instead of VARCHAR/CHAR, so no character outside the codepage is silently replaced."),
 new RuleDefinition(SarifRuleCatalog.WriteLossApproximateTruncationRuleId, "An INSERT/UPDATE or SET variable assignment assigns an approximate-numeric (REAL/FLOAT) value to an exact integer target - the fractional part is silently dropped, with no error.", "Round the value explicitly before assigning it to the exact integer target, or widen the target to a type that keeps the fractional part."),
 new RuleDefinition(SarifRuleCatalog.WriteLossNumericScaleNarrowingRuleId, "An INSERT/UPDATE or SET variable assignment assigns a DECIMAL/NUMERIC value to a target with a smaller scale - digits past the target's scale are silently rounded away, with no error.", "Widen the target column's scale to match the source value, or round the value explicitly before assigning it."),
 new RuleDefinition(SarifRuleCatalog.WriteLossTemporalPrecisionLossRuleId, "An INSERT/UPDATE or SET variable assignment assigns a DATETIME/DATETIME2/SMALLDATETIME/DATETIMEOFFSET value to a DATE target - the time-of-day component is silently dropped, with no error.", "Widen the target column to a type that keeps the time-of-day component, or drop it explicitly with CAST before assigning if that's genuinely intended."),
 new RuleDefinition(SarifRuleCatalog.TvfFenceCorrelatedApplyRuleId, "A CROSS/OUTER APPLY calls a multi-statement or CLR table-valued function with an argument correlated to an outer row - the whole function body re-executes once per outer row, and interleaved execution (2017+) does not rescue this.", null, ["tests/SilentScan.Tests/fixtures/tvf_fence/CORRELATED_APPLY_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.TvfFenceNestedUnderViewOrTvfRuleId, "A view or inline TVF referenced here is itself, transitively, built over a multi-statement/CLR TVF - the fence and its fabricated cardinality estimate are inherited invisibly through however many layers sit between.", null, ["tests/SilentScan.Tests/fixtures/tvf_fence/NESTED_UNDER_VIEW_OR_TVF_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.TvfFenceFromOrJoinRuleId, "A FROM/JOIN references a multi-statement/CLR table-valued function directly - the optimizer cannot see into its body, so the reference carries a fixed cardinality estimate (1 row legacy CE / 100 rows 2014+ CE) that propagates into the surrounding plan.", null, ["tests/SilentScan.Tests/fixtures/tvf_fence/FROM_OR_JOIN_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.TvfFenceInsertExecRuleId, "An INSERT ... EXEC forces the executed procedure's entire result set to be spooled to a worktable before insertion - the same fence family, reached from a procedure call rather than a function reference.", null, ["tests/SilentScan.Tests/fixtures/tvf_fence/INSERT_EXEC_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.TvfFenceStandaloneRuleId, "A standalone SELECT references a multi-statement/CLR table-valued function with nothing else in the FROM clause - the fence and its fixed estimate are real, but there is no surrounding plan for the estimate to poison.", null, ["tests/SilentScan.Tests/fixtures/tvf_fence/STANDALONE_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.ScalarUdfPredicateInvocationRuleId, "A scalar UDF is called in a WHERE/JOIN ON/HAVING/MERGE ON predicate - per-row execution, non-sargable, and (pre-2019, or on any engine when the UDF proves non-inlineable) forces the whole plan serial. Distinct from a syntactic function-wrapped-column finding on the same predicate: this claim is catalog-proven per-row/serial cost, not sargability loss, and the two are reported independently by design.", null, ["tests/SilentScan.Tests/fixtures/scalar_udf/PREDICATE_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.ScalarUdfNestedUnderViewOrTvfRuleId, "A view or inline TVF referenced here calls a scalar UDF, transitively, somewhere in its own definition - the per-row cost (and, pre-2019, forced-serial plan) is inherited invisibly through however many layers sit between. Pre-2019 an inline TVF's expansion spreads the UDF into every caller; 2019+ a scalar-UDF call inside an iTVF is itself a FROID inlining-blocker interaction.", null, ["tests/SilentScan.Tests/fixtures/scalar_udf/NESTED_UNDER_VIEW_OR_TVF_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.ScalarUdfSchemaDependencyRuleId, "A computed column, DEFAULT, or CHECK constraint definition calls a scalar UDF - this poisons every query that touches the table with per-row/serial cost, even one that never names the column, and is detected from the catalog alone.", null, ["tests/SilentScan.Tests/fixtures/scalar_udf/COMPUTED_COLUMN_fires.sql", "tests/SilentScan.Tests/fixtures/scalar_udf/DEFAULT_CONSTRAINT_fires.sql", "tests/SilentScan.Tests/fixtures/scalar_udf/CHECK_CONSTRAINT_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.ScalarUdfProjectionInvocationRuleId, "A scalar UDF is called outside any predicate (SELECT list, ORDER BY, GROUP BY, SET/variable assignment) - per-row execution and (pre-2019, or non-inlineable) a forced-serial plan, but sargability is unaffected.", null, ["tests/SilentScan.Tests/fixtures/scalar_udf/SELECT_LIST_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.ColumnCollationDriftRuleId, "A string-family column's own collation differs from the database's default collation (or, for a temp table/table variable, from tempdb's effective collation) - a conversion seed: any future comparison against a column/literal carrying the baseline collation risks a collation-conflict compile error or a forced-scan implicit conversion. Catalog-only, detected before any query reaches the column."),
 new RuleDefinition(SarifRuleCatalog.CrossTableTypeDriftRuleId, "A foreign-key column pair's declared types and/or collations genuinely differ - a conversion seed on every JOIN that follows this relationship, detected from the catalog alone (sys.foreign_key_columns), independent of whether any scanned query actually joins on it."),
 new RuleDefinition(SarifRuleCatalog.ProcCallArgumentMismatchRuleId, "A real EXEC call site passes a caller-side variable whose declared type risks silent data loss against the callee's own declared parameter type - an assignment-shaped conversion at parameter marshalling, not a predicate, classified the same way an INSERT/UPDATE assignment's silent data loss is."),
 new RuleDefinition(SarifRuleCatalog.TemporalBoundaryPrecisionRuleId, "A BETWEEN predicate's upper bound literal has fewer fractional-second digits than the TIME/DATETIME2/DATETIMEOFFSET column's own declared precision - a correctness bug, not a sargability one: rows in the precision gap are silently excluded, oracle-confirmed. Rewrite as >= start AND < (start of the next period) instead.", "Rewrite the BETWEEN predicate as >= start AND < (start of the next period) instead, so no value in the precision gap is silently excluded.", ["tests/SilentScan.Tests/fixtures/tier1/TEMPORAL_BOUNDARY_PRECISION_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.MaxTypedColumnRuleId(NonIndexableColumnFindingKind.MaxLength), "A string/binary column is declared MAX-typed - it can never be an index key column at all, so any predicate/join on it can never seek regardless of how it's used. Catalog-only structural fact."),
 new RuleDefinition(SarifRuleCatalog.MaxTypedColumnRuleId(NonIndexableColumnFindingKind.LegacyLargeObject), "A column is declared TEXT/NTEXT/IMAGE (legacy large-object types) - it can never appear in any index at all, not even as a nonclustered index's INCLUDE column, so any predicate/join on it can never seek and it can never be covered. Stronger than the MAX-typed-column fact: MAX-typed columns can still be carried as an INCLUDE column, these cannot. Catalog-only structural fact.", "Migrate away from the deprecated TEXT/NTEXT/IMAGE types to VARCHAR(MAX)/NVARCHAR(MAX)/VARBINARY(MAX), which at least support being carried as a covering INCLUDE column."),
 new RuleDefinition(SarifRuleCatalog.ColumnstoreUnsupportedColumnTypeRuleId, "A SQL_VARIANT column participates in a columnstore index on the same table - oracle-confirmed this does not deploy at all (Msg 35343: \"Column '...' has a data type that cannot participate in a columnstore index\"), whether the column sits on a table carrying a whole-table clustered columnstore index or is explicitly named in a nonclustered columnstore index's own column list. Catalog-only structural fact.", "Remove the SQL_VARIANT column from the columnstore index's scope: retype it to a concrete type, move it to a separate non-columnstore-indexed table, or (for a nonclustered columnstore index only) drop it from the index's own explicit column list."),
 new RuleDefinition(SarifRuleCatalog.FloatEqualityRuleId, "A WHERE/ON equality predicate (=) compares a float/real (approximate, IEEE-754) column - two values a person would call the same number can carry a different bit pattern and compare unequal, so the predicate can silently return the wrong rows regardless of plan shape or indexing."),
 new RuleDefinition(SarifRuleCatalog.AlwaysEncryptedOrderByRuleId, "An ORDER BY clause references an Always Encrypted column - oracle-confirmed the statement never compiles at all (Msg 33277), for both DETERMINISTIC and RANDOMIZED encryption types, regardless of whether the connecting client is itself Always-Encrypted-enabled - sorting by ciphertext has no relationship to plaintext order.", "Remove the encrypted column from the ORDER BY clause, or sort by a different, non-encrypted column instead - Always Encrypted has no supported way to sort by an encrypted column's real value.", ["tests/SilentScan.Tests/fixtures/predicates/ALWAYS_ENCRYPTED_ORDER_BY_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.TriggerOrderRuleId, "A table carries two or more enabled AFTER triggers for the same firing event (INSERT/UPDATE/DELETE) with no sp_settriggerorder pin narrowing their relative order down to a single pair - oracle-confirmed sys.trigger_events.is_first/is_last report the real pin state directly, and the engine documents that firing order among unpinned triggers on the same event is undefined. Catalog-only, detected without needing to see any query that touches the table.", "Pin the triggers with sp_settriggerorder (FIRST/LAST), or consolidate the logic into a single trigger, so no two triggers on the same event are left with an undefined relative order."),
 new RuleDefinition(SarifRuleCatalog.OperandComparabilityRuleId(OperandComparabilityFindingKind.Xml), "An xml column is used in a comparison, IN list, BETWEEN, NULLIF, ORDER BY, GROUP BY, or SELECT DISTINCT - oracle-confirmed the statement never compiles (Msg 305/402/421 depending on the shape): the XML data type cannot be compared or sorted at all, except IS NULL.", "Remove the xml column from the comparison/ordering/grouping/DISTINCT position - shred the value with .value()/.nodes() to a comparable scalar type first if the comparison is genuinely needed.", ["tests/SilentScan.Tests/fixtures/predicates/XML_OPERAND_NOT_COMPARABLE_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.OperandComparabilityRuleId(OperandComparabilityFindingKind.LegacyLargeObject), "A TEXT/NTEXT/IMAGE column is used in a comparison, IN list, BETWEEN, NULLIF, ORDER BY, or GROUP BY - oracle-confirmed the statement never compiles (Msg 306/402/421 depending on the shape): these legacy large-object types cannot be compared or sorted, except IS NULL or LIKE.", "Migrate the column to VARCHAR(MAX)/NVARCHAR(MAX)/VARBINARY(MAX), which support ordinary comparison, or remove it from the comparison/ordering/grouping/DISTINCT position.", ["tests/SilentScan.Tests/fixtures/predicates/LEGACY_LOB_OPERAND_NOT_COMPARABLE_fires.sql"]),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternTableVariablePspSkipRuleId, "A table-valued parameter creates the engine's TableVariable Parameter Sensitive Plan skip condition at compatibility level 170 or later. Any statement in the module that would otherwise qualify for PSP cannot receive PSP plan variants.", "Move the PSP-sensitive statement into a module without a table-valued parameter, or use a different data-passing design when multiple PSP plan variants are required."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternTableVariableLowCompatEstimateRuleId, "A table variable is used as a query source while the connected database's compatibility level is below 150 - oracle-confirmed the optimizer's cardinality estimate is fixed at exactly 1 row regardless of how many rows were actually loaded, below that level. Exception, also oracle-confirmed: a session running under DBCC TRACEON(11034) gets a real cardinality estimate instead, at any compatibility level - a session trace flag isn't visible to static analysis, so this rule can false-positive under it."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternTableVariableStaleEstimateInLoopRuleId, "A table variable is read as a query source inside a WHILE loop that also writes to it - oracle-confirmed the cardinality estimate freezes at the row count from the first iteration that executed the read and never re-adjusts as the loop keeps growing the table variable."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternRbarSingleRowLoopDmlRuleId, "A WHILE loop issues a single-row UPDATE/DELETE keyed to a variable the same loop advances per iteration (row-by-row processing) - a set-based statement over the whole matching set would do the same work without the per-iteration overhead.", "Rewrite the loop as a single set-based UPDATE/DELETE over the whole matching set instead of looping row by row."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternGlobalCursorDeclarationRuleId, "A cursor is declared without LOCAL, defaulting to GLOBAL - it stays alive and visible for the whole connection/batch, not just the declaring scope, a resource-leak and naming-collision risk.", "Declare the cursor LOCAL explicitly instead of relying on the GLOBAL default."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternCountStarVariableExistenceCheckRuleId, "COUNT(*) is assigned to a variable and the very next statement compares that variable only to zero - oracle-confirmed this shape forces a real full-set aggregation, unlike the inline scalar-subquery form (IF (SELECT COUNT(*) ...) > 0), which the optimizer already rewrites into an EXISTS-equivalent short-circuiting plan.", "Use IF EXISTS(SELECT 1 ...) or the inline scalar-subquery form (IF (SELECT COUNT(*) ...) > 0) instead of assigning COUNT(*) to a variable before comparing it to zero."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternNonAggregateHavingPredicateRuleId, "A HAVING condition references only GROUP BY key columns/literals and no aggregate result - moving it to WHERE produces an identical result while filtering before, not after, aggregation.", "Move the condition from HAVING to WHERE so filtering happens before aggregation instead of after."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternUnionOfProvablyDisjointBranchesRuleId, "A UNION combines branches that each filter the same table/column to a distinct literal - the branches are provably mutually exclusive, so UNION's duplicate-elimination pass can never remove a row and UNION ALL is equivalent.", "Use UNION ALL instead of UNION - the branches are provably disjoint, so no duplicate-elimination pass is ever needed."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternDistinctMaskingJoinFanoutRuleId, "A SELECT DISTINCT joins a table whose own join columns are not backed by a unique index - DISTINCT may be silently papering over row duplication the join itself introduces."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternUnqualifiedTableReferenceRuleId, "A table reference at a real query site carries no explicit schema qualifier - the plan cache holds a separate entry per schema-resolution context and compilation takes an extra schema-stability lock.", "Qualify the table reference with its schema explicitly instead of relying on schema resolution at compile time."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternMergeMissingHoldlockRuleId, "A MERGE target carries no WITH (HOLDLOCK)/SERIALIZABLE hint - the documented MERGE race where two concurrent sessions can both take the WHEN NOT MATCHED branch under READ COMMITTED and hit a primary-key violation.", "Add a WITH (HOLDLOCK) or SERIALIZABLE hint to the MERGE target to close the race."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternMergeNonUniqueUsingSourceRuleId, "A MERGE USING source is not backed by a unique index covering its own ON-clause join columns - the engine raises a hard error the moment a target row matches more than one source row.", "Add a unique index/constraint covering the MERGE USING source's own ON-clause join columns."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternMergeUnconditionalDeleteRuleId, "A MERGE WHEN MATCHED/WHEN NOT MATCHED BY SOURCE THEN DELETE branch carries no additional AND condition of its own - a badly-scoped USING source can turn an intended incremental sync into a mass delete.", "Add an explicit AND condition to the MERGE DELETE branch to scope which rows it can remove."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternRecursiveCteMissingMaxRecursionRuleId, "A recursive CTE's containing statement has no OPTION (MAXRECURSION n) - oracle-confirmed the engine's own default 100-level limit fails the statement outright (Msg 530) once exceeded.", "Add an explicit OPTION (MAXRECURSION n) to the statement instead of relying on the engine's default 100-level limit."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternUnboundedTableWriteRuleId, "An UPDATE/DELETE has no WHERE clause and no TOP - a whole-table write with no row-limiting mechanism at all. Advisory: a deliberate full-table maintenance statement is a legitimate reason this fires."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternLinkedServerOrCrossDatabaseReferenceRuleId, "A table reference names a remote linked server (4-part name) or a different database than the one this scan connected to (3-part name) - remote/cross-database statistics are usually unavailable to the optimizer, so any cardinality estimate involving one is close to a guess."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternMultiRowInsertIgnoreDupKeyDropRuleId, "A multi-row INSERT targets a table with a UNIQUE index built WITH (IGNORE_DUP_KEY = ON) - oracle-confirmed a duplicate-key row is silently skipped (no error, no exception) while the rest of the batch commits; an UPDATE creating the same duplicate still raises a real error regardless of this option.", "Remove IGNORE_DUP_KEY from the index if silent row loss on a duplicate key is not the intended behavior, or check @@ROWCOUNT against the number of rows the statement named to detect a silent drop."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchColumnMismatchRuleId, "An ALTER TABLE ... SWITCH statement's source and target tables have a structural column mismatch (different column count, a renamed column at the same ordinal, a column computed on one side only, or a differing data type/length/precision/scale) - oracle-confirmed each shape raises a real, specific engine error (4943/4942/4965/4944) before any data-dependent check runs, regardless of table content.", "Make the source and target tables' column definitions match exactly at every ordinal (name, type, computed-ness) before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchIndexMismatchRuleId, "An ALTER TABLE ... SWITCH statement's source and target tables disagree on clustered-index presence, or the target carries a non-clustered index (key columns, sort direction, or INCLUDE columns) with no identical counterpart on the source - oracle-confirmed each shape raises a real engine error (4913/4914/4947) before any data-dependent check runs.", "Give the source table an identical clustered-index presence and an identical counterpart for every index the target table carries, before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchConstraintMismatchRuleId, "An ALTER TABLE ... SWITCH statement's source and target tables disagree on CHECK or FOREIGN KEY constraints - a target constraint with no matching source counterpart, or a matching pair (matched by definition/shape, not name) that disagrees on enabled/disabled or NOCHECK/CHECK trust state - oracle-confirmed each shape raises a real engine error (4970/4971/4960/4968/4969/4974) before any data-dependent check runs.", "Give the source table an identical (same definition, same enabled/trust state) counterpart for every CHECK and FOREIGN KEY constraint the target table carries, before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchTargetOnlyIndexRestrictionRuleId, "An ALTER TABLE ... SWITCH statement's target table carries an XML or spatial index - oracle-confirmed this fails unconditionally (error 4983) regardless of whether the source table has one too, which the engine explicitly allows.", "Move the XML or spatial index off the target table, or restructure the SWITCH so the table carrying the index is the source, not the target."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchFilegroupMismatchRuleId, "An ALTER TABLE ... SWITCH statement's source and target tables reside in different filegroups, or either resides in a filegroup currently marked read-only - oracle-confirmed each shape raises a real engine error (4940/4979) before any data-dependent check runs.", "Put the source and target tables in the same, currently read-write filegroup before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchTemporalMismatchRuleId, "An ALTER TABLE ... SWITCH statement's source and target tables disagree on system-versioning (one has a PERIOD FOR SYSTEM_TIME, the other doesn't) - oracle-confirmed this raises a real engine error (13577) unconditionally.", "Make both the source and target tables agree on system-versioning (both system-versioned, or neither) before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchRuleConstraintRuleId, "An ALTER TABLE ... SWITCH statement's source or target table carries a legacy CREATE RULE/sp_bindrule column binding - oracle-confirmed this raises a real engine error (4964) unconditionally, on either side.", "Unbind the RULE from the column (sp_unbindrule), or replace it with a modern CHECK constraint, before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchCdcPartitionSwitchRuleId, "An ALTER TABLE ... SWITCH PARTITION statement's source or target table is enabled for Change Data Capture with @allow_partition_switch explicitly set to 0 - oracle-confirmed this raises a real engine error (22842/22843), while the default setting does not.", "Re-enable the CDC capture instance with @allow_partition_switch = 1 (sp_cdc_disable_table then sp_cdc_enable_table), or drop CDC tracking from the table, before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchPartitionFilegroupMismatchRuleId, "An ALTER TABLE ... SWITCH PARTITION statement's source and target sides resolve to different filegroups at the specific partition number named - oracle-confirmed this raises a real engine error (4938/4939), a more granular check than the whole-table filegroup match.", "Put the source and target partitions (or the non-partitioned side and the other side's specific partition) in the same filegroup before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.QueryAntiPatternAlterTableSwitchFullTextIndexRestrictionRuleId, "An ALTER TABLE ... SWITCH statement's source or target table carries a full-text index - oracle-confirmed this raises error 4918 unconditionally.", "Remove the full-text index from the source and target tables before running the SWITCH."),
 new RuleDefinition(SarifRuleCatalog.IndexCoverageKeyLookupProneIndexRuleId, "A WHERE-equality seek against a table's own single candidate nonclustered index does not cover every other column the statement references on that table - oracle-confirmed via real plan XML that this shape produces a Key/RID Lookup (Lookup=\"1\") per matched row, and that widening the index to cover those columns removes it.", "Widen the nonclustered index to cover (via key columns or INCLUDE) every column the statement references on that table, removing the Key/RID Lookup."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessMultiRowUnsafeSingleRowAssignmentRuleId, "A variable is assigned from a single, unspecified row of inserted/deleted with no WHERE/TOP/aggregate - oracle-confirmed the engine silently binds one arbitrary row's value and discards the rest whenever the trigger's own multi-row DML fires it more than once.", "Replace the single-row assignment with set-based logic (a join, aggregate, or cursor) that processes every row of inserted/deleted, not just one."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessMultiRowUnsafeKeyedDmlRuleId, "The same unsafe single-row inserted/deleted assignment, where the resulting variable then drives a keyed UPDATE/DELETE straight-line in the same trigger body - the arbitrary single value ends up actually written back instead of every affected row.", "Replace the single-row variable-driven UPDATE/DELETE with a set-based statement joined to inserted/deleted so every affected row is written, not just one."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessNoEarlyOutForEmptyInvocationRuleId, "A trigger body has no IF NOT EXISTS(SELECT * FROM inserted/deleted)/IF @@ROWCOUNT = 0 RETURN-style guard - a well-documented convention to skip unnecessary work on an empty invocation, advisory only.", "Add an IF NOT EXISTS(SELECT * FROM inserted/deleted)/IF @@ROWCOUNT = 0 RETURN guard at the top of the trigger body."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessDirectRecursiveTriggerRuleId, "A trigger writes directly back to its own target table while the connected database's own RECURSIVE_TRIGGERS option is live-confirmed ON - oracle-confirmed this actually re-fires the trigger rather than silently no-oping."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessInsteadOfInsertFilteredNoRejectPathRuleId, "An INSTEAD OF INSERT trigger re-inserts a WHERE/JOIN-filtered subset of inserted with no companion branch handling the excluded rows - oracle-confirmed the caller's own INSERT reports success while the filtered-out rows are silently dropped, no error, no row-count signal without inspecting @@ROWCOUNT against the input batch size.", "Add a companion branch that explicitly handles the rows the WHERE/JOIN filter excludes, instead of silently dropping them."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessUpdateFunctionWithoutValueComparisonRuleId, "A trigger gates its logic on UPDATE(column) alone with no comparison between inserted.column and deleted.column - oracle-confirmed UPDATE() reports whether a column was named in the SET list, not whether its value actually changed, so a full-column UPDATE from an ORM trips the branch on genuine no-op saves as often as real changes.", "Compare inserted.column against deleted.column directly instead of relying on UPDATE(column) alone, which only reports whether the column was named in the SET list."),
 new RuleDefinition(SarifRuleCatalog.TriggerCorrectnessLogonTriggerHostNameGateRuleId, "A logon trigger gates an allow/deny decision on HOST_NAME() - oracle-confirmed this value is client-supplied via the connection string and trivially spoofable, so the access control does not actually control anything.", "Do not gate an access control decision on HOST_NAME() - it is client-supplied over the connection string and trivially spoofable."),
 new RuleDefinition(SarifRuleCatalog.CrossModuleLockOrderRuleId, "Two top-level procedures' own direct explicit-transaction write orders disagree on the relative lock order of the same two base tables - the textbook cross-session deadlock shape.", "Make both procedures acquire locks on the two tables in the same relative order."),
 new RuleDefinition(SarifRuleCatalog.TriggerRecursionCycleRuleId, "A directed cycle of triggers across two or more distinct tables (table A's trigger writes to table B, whose own trigger writes back toward A) - oracle-confirmed reachable while the server's own 'nested triggers' option is on, and confirmed to hit a real Msg 217 nesting-level-exceeded error once the cascade runs unbounded."),
 new RuleDefinition(SarifRuleCatalog.OversizedParameterRuleId, "A predicate compares a column against a parameter/variable/expression declared with a meaningfully longer length than the column itself - risks memory-grant inflation once the value feeds a sort/hash operator. Structural report, not a plan-shape claim for this specific predicate.", "Declare the parameter/variable/expression with a length matching the column's, rather than meaningfully longer, to avoid inflating the memory grant."),
 new RuleDefinition(SarifRuleCatalog.UnderLengthParameterRuleId, "A predicate compares a column against a parameter/variable/expression declared with a meaningfully shorter length than the column itself, or with no explicit length at all (T-SQL defaults to length 1) - the value is silently truncated before the predicate ever runs, changing which rows match or matching none. Structural report, same severity tier as WriteLossFinding's identical class of concern.", "Declare the parameter/variable/expression with a length at least as long as the column's, so the value isn't silently truncated before the predicate runs."),
 new RuleDefinition(SarifRuleCatalog.AnsiPaddingMismatchRuleId, "A LIKE predicate compares a non-ANSI-padded varchar/varbinary column against a literal pattern with significant trailing whitespace - the column can never store a value ending in whitespace at all (stripped at INSERT time under ANSI_PADDING OFF), so the pattern can never match anything the column could ever contain. Data-semantics finding, not a plan-shape one."),
 new RuleDefinition(SarifRuleCatalog.CatchAllPredicateRuleId, "A predicate of the shape (Col = @p OR @p IS NULL) - the 'catch-all'/'kitchen-sink' optional-filter idiom. One cached plan must stay correct for every possible NULL/non-NULL state of @p, which typically forces a scan regardless of what value is actually passed. Suppressed when the statement carries OPTION (RECOMPILE) or the procedure is WITH RECOMPILE, both of which let the optimizer see the real value on each call.", "Add OPTION (RECOMPILE) to the statement, or WITH RECOMPILE to the procedure, so the optimizer compiles against the real parameter value on each call instead of one plan that must suit every NULL/non-NULL state."),
 new RuleDefinition(SarifRuleCatalog.LocalVariablePredicateRuleId, "A predicate compares a column against a DECLARE'd local variable's value, never a formal parameter - the value is invisible to the cardinality estimator, which falls back to the column's average-density statistic instead of a value-specific estimate. The predicate is still fully sargable; only the row-count ESTIMATE is at risk, not the access path. Suppressed when the statement carries OPTION (RECOMPILE) or the procedure is WITH RECOMPILE.", "Add OPTION (RECOMPILE) to the statement, or WITH RECOMPILE to the procedure, so the cardinality estimate is built from the real value instead of the column's average density."),
 new RuleDefinition(SarifRuleCatalog.FilteredIndexParameterMismatchRuleId, "A predicate compares a column against a parameter or local variable, but that same column carries a filtered index whose own filter is a literal-equality restatement of this exact comparison - the optimizer can only match a filtered index against a query that restates its filter with a LITERAL, never a parameter/variable, so this query can never use that index regardless of the runtime value. Not suppressed by OPTION (RECOMPILE) - a compile-time limitation, not a cardinality-estimate one."),
 new RuleDefinition(SarifRuleCatalog.NotInNullableSubqueryRuleId, "WHERE x NOT IN (SELECT y FROM t) where y is a nullable column - a three-valued-logic correctness trap. The instant the subquery produces one NULL row, the whole NOT IN evaluates to UNKNOWN for every outer row, so the query silently returns zero rows instead of the expected anti-join result. Never fires when the subquery column is NOT NULL, or when the subquery already filters it with an unconditional WHERE y IS NOT NULL.", "Add a WHERE y IS NOT NULL filter to the subquery (or rewrite the NOT IN as a NOT EXISTS), so a NULL row can't collapse the whole predicate to UNKNOWN."),
 new RuleDefinition(SarifRuleCatalog.NonUniqueUpdateSourceRuleId, "UPDATE ... FROM ... JOIN where the joined source's own join columns carry no unique index/constraint - if a target row matches more than one source row, SQL Server silently picks a value from an unspecified one of them (plan-dependent, not guaranteed stable across executions). MERGE raises a hard error in this exact situation instead of picking silently. Never fires when the source's join columns are covered by a genuine unique index/constraint, or when the SET clause never reads from the non-unique source.", "Add a unique index/constraint covering the source's join columns, or switch to MERGE, which raises a hard error instead of silently picking an unspecified row."),
 new RuleDefinition(SarifRuleCatalog.ForcedSerialTableVariableModificationRuleId, "A DECLARE'd table variable is the write target of an INSERT/UPDATE/DELETE/MERGE, or the INTO target of an OUTPUT clause - the engine forces that one statement's own plan serial (effective MAXDOP 1), confirmed as NonParallelPlanReason=\"TableVariableTransactionsDoNotSupportParallelNestedTransaction\" in a real executed plan. A read-only reference to the same table variable is unaffected."),
 new RuleDefinition(SarifRuleCatalog.ForcedSerialFastForwardCursorRuleId, "A cursor declared FAST_FORWARD (or the equivalent bare FORWARD_ONLY READ_ONLY without an explicit STATIC/KEYSET/DYNAMIC) forces the cursor's own defining query plan serial, confirmed as NonParallelPlanReason=\"NoParallelFastForwardCursor\". This is the opposite of the common 'always use LOCAL FAST_FORWARD' fetch-overhead advice - that advice is still correct for row-by-row fetch cost, but it is specifically what defeats a parallel plan for the cursor's defining SELECT."),
 new RuleDefinition(SarifRuleCatalog.ForcedSerialNonParallelizableIntrinsicRuleId, "One of a finite, oracle-confirmed list of intrinsic functions/globals (OBJECT_ID, IDENT_CURRENT, ERROR_NUMBER, ERROR_MESSAGE, ERROR_LINE, ERROR_SEVERITY, ERROR_STATE, ERROR_PROCEDURE, @@TRANCOUNT) referenced inside a query with a real FROM clause forces that query's plan serial, confirmed as NonParallelPlanReason=\"NonParallelizableIntrinsicFunction\"."),
 new RuleDefinition(SarifRuleCatalog.UntrustedForeignKeyRuleId, "A foreign key the engine itself does not trust (sys.foreign_keys.is_not_trusted) - almost always the result of a WITH NOCHECK re-enabling ALTER TABLE statement. Forfeits join-elimination and other constraint-based query rewrites for every query that touches it."),
 new RuleDefinition(SarifRuleCatalog.UntrustedCheckConstraintRuleId, "A CHECK constraint the engine itself does not trust (sys.check_constraints.is_not_trusted) - almost always the result of a WITH NOCHECK re-enabling ALTER TABLE statement. The constraint may not actually hold over existing rows, and the optimizer forfeits constraint-based rewrites that assume it does."),
 new RuleDefinition(SarifRuleCatalog.CheckConstraintNullNotHandledRuleId, "A nullable column's own CHECK constraint predicate has no IS NULL/IS NOT NULL test against that column anywhere in the predicate - SQL Server's three-valued logic means a comparison against NULL evaluates to UNKNOWN, never FALSE, and a CHECK constraint only rejects a row when its predicate is FALSE, so a NULL value silently passes a constraint that reads as if it forbids bad data.", "Add an explicit IS NULL/IS NOT NULL test for the column in the CHECK constraint predicate, so a NULL value isn't silently accepted through three-valued logic."),
 new RuleDefinition(SarifRuleCatalog.CheckConstraintOnIdentityColumnRuleId, "A CHECK constraint's own definition directly references an IDENTITY column - the identity counter advances even through a failed insert, so a numeric-threshold CHECK here rejects every insert deterministically until the counter happens to satisfy it, then silently stops mattering forever with no code change.", "Do not enforce a numeric-threshold CHECK directly on an IDENTITY column - the counter advances even on failed inserts, so the constraint stops meaningfully applying once it happens to be satisfied."),
 new RuleDefinition(SarifRuleCatalog.DefaultNullableConstraintRuleId, "A column carries a DEFAULT constraint but is still nullable - a DEFAULT only ever applies when the column is OMITTED from an INSERT's own column list; any caller that supplies NULL explicitly (a common ORM-generated full-column INSERT shape) bypasses the default entirely, silently, with no error.", "Make the column NOT NULL, or otherwise stop relying on the DEFAULT for callers that supply NULL explicitly - a DEFAULT only applies when the column is omitted from the INSERT's own column list."),
 new RuleDefinition(SarifRuleCatalog.TryCastComputedColumnPredicateRuleId, "A non-persisted computed column built on TRY_CAST is referenced inside a real filter-context predicate (WHERE/JOIN ON/HAVING) elsewhere in the corpus - TRY_CAST is session-DATEFORMAT-dependent and therefore classified non-deterministic by the engine, so this column can never be PERSISTED or indexed at all, and the predicate can never seek through it no matter what index exists elsewhere on the table."),
 new RuleDefinition(SarifRuleCatalog.StaleSelectStarViewRuleId, "A view's own outermost SELECT * over a single base table has a compiled column list (frozen at CREATE/ALTER/sp_refreshview time) that no longer matches that base table's current column list - a later ALTER TABLE ADD/DROP COLUMN never propagates to the view. Confirmed to silently surface real data under a stale, wrong column label when a drop and a later add shift column identity, not merely a missing/extra column."),
 new RuleDefinition(SarifRuleCatalog.BareTopNoOrderByRuleId, "A bare TOP (n) with no ORDER BY anywhere in the same query - SQL Server documents that without ORDER BY, both which rows satisfy TOP and their return order are unguaranteed, so code relying on 'the first N rows' is trusting undefined behavior that can change with plan choice, parallelism, or statistics drift, not merely a stylistic complaint. TOP (100) PERCENT is excluded - 100 percent of a result set is every row regardless of TOP's own row-selection nondeterminism.", "Add an explicit ORDER BY to the query so which rows TOP returns (and their order) is guaranteed, not left to plan choice."),
 new RuleDefinition(SarifRuleCatalog.StringConcatNullRuleId, "A + concatenation chain between string-typed operands where at least one operand is a nullable column with no ISNULL/COALESCE guard - unlike CONCAT(), which treats a NULL operand as empty string, + propagates a single NULL operand to NULL for the WHOLE expression with no error raised, oracle-confirmed directly against CONCAT()'s own different behavior for the identical NULL input.", "Add an ISNULL/COALESCE guard around the nullable operand, or use CONCAT() instead of +, which treats a NULL operand as empty string rather than propagating NULL to the whole expression."),
 new RuleDefinition(SarifRuleCatalog.AggregateDivisionColumnstoreRuleId, "An aggregate argument contains a CASE-guarded division by a non-constant divisor, on a table backed by a columnstore index - historically reported as a class of bug where batch-mode (vectorized) execution does not reliably preserve the same per-row CASE-branch short-circuit elision rowstore scalar execution provides, so a query that has run safely under rowstore can start raising a divide-by-zero error once its plan runs in batch mode. Shipped as a structural risk flag only after a genuine but unsuccessful attempt to reproduce a live failure against this tool's own standing engine build - not a proven-current-behavior claim."),
 new RuleDefinition(SarifRuleCatalog.SecurityPredicateIndexRuleId, "An enabled Row-Level Security FILTER predicate's own bound column(s) lead no active index on the secured table - the predicate is silently applied to every SELECT/UPDATE/DELETE against this table (not just queries whose own WHERE clause happens to filter the same way), so the engine cannot seek and must evaluate it as a residual, per-row filter over a full scan on every access. Oracle-confirmed scan-vs-seek contrast; the checklist's own 'forces single-threaded execution' claim was not reproduced live on this tool's own standing engine build and is deliberately not asserted here.", "Add an index (or extend an existing one) covering the Row-Level Security FILTER predicate's own bound column(s), so it can be seek-evaluated instead of scanned on every access."),
 new RuleDefinition(SarifRuleCatalog.DanglingObjectReferenceRuleId, "A stored procedure, view, function, or trigger names a table/view/synonym the engine's own binder cannot resolve to a real object right now - CREATE/ALTER succeeds anyway because SQL Server defers name resolution for a module body until it actually runs, so the module compiles clean and sits in the catalog looking correct until the first call that reaches the missing reference, which fails with Msg 208 (\"Invalid object name\"). Oracle-confirmed directly: a procedure referencing a table that was never created raises exactly that error at EXEC time despite a clean CREATE PROCEDURE. Candidates are found from the persisted sys.sql_expression_dependencies catalog view, then each one is reconciled against the engine's own live sys.dm_sql_referenced_entities answer right now before being reported, so a candidate whose dependency entry has simply gone stale (the missing object was created since) is never reported as a false positive."),
 new RuleDefinition(SarifRuleCatalog.CascadingForeignKeyRuleId, "A foreign key with a non-NO_ACTION ON DELETE/ON UPDATE action - a single DML statement against the referenced table silently cascades to every dependent row in the child table too, with no visible predicate change at the call site."),
 new RuleDefinition(SarifRuleCatalog.MultiReferencedCteRuleId, "A CTE referenced 2+ times downstream of its own WITH clause - SQL Server does not materialize a plain CTE once and reuse it, so each reference independently re-runs the CTE's own defining query. A self-reference inside a recursive CTE's own body is never counted - that is the structurally mandated recursion mechanism, not optional re-invocation.", "Materialize the CTE's result into a #temp table or table variable if it's referenced more than once, so the defining query runs once instead of once per reference."),
 new RuleDefinition(SarifRuleCatalog.NestedViewDepthRuleId, "A view/inline TVF nested 2+ view/TVF layers deep before reaching a base table - a change to a base table now has to be traced through 2+ independent view layers before its blast radius is understood, and each layer is a place a SELECT */column-list mismatch or silent type widening can hide."),
 new RuleDefinition(SarifRuleCatalog.PostExpansionJoinWidthRuleId, "A query whose written FROM/JOIN table count meaningfully understates how many base tables it actually touches once every view/inline-TVF reference is expanded transitively - a query that looks like a 3-table join can expand to 20."),
 new RuleDefinition(SarifRuleCatalog.SelectStarViewRuleId, "A view/inline TVF nested 1+ view/TVF layers deep whose own outermost SELECT is a bare or qualified * - its column list is frozen at CREATE/ALTER time and silently disagrees with the base table after any change, confirmed to survive even a live describe-only probe and real execution until sp_refreshview runs. Only fires when a real consuming query elsewhere explicitly selects a strict, named subset of the view's full column set - a consumer that itself does SELECT * never narrows anything and is never matched.", "Run sp_refreshview (or ALTER/CREATE the view) to resync its column metadata with the base table - avoid a bare SELECT * in a view definition to prevent this recurring."),
 new RuleDefinition(SarifRuleCatalog.ConcatenatedValueInConstantSqlRuleId, "A proven-constant value was spliced into an EXEC/sp_executesql dynamic SQL string via concatenation rather than authored as one whole literal or passed through sp_executesql's own parameter mechanism - every distinct concatenated value compiles its own cached plan, oracle-confirmed against sys.dm_exec_cached_plans.", "Pass the value through sp_executesql's own @params mechanism instead of concatenating it into the SQL text, so one cached plan can be reused across every distinct value."),
 new RuleDefinition(SarifRuleCatalog.ExecStringConcatenatesParameterizableValueRuleId, "An EXEC(string)/EXEC(@sql) call site concatenates a proven-constant value into its SQL text - sp_executesql's own @params mechanism was available and unused, and would have let this call site reuse one cached plan across every distinct value instead of compiling a new one each time.", "Use sp_executesql with its own @params mechanism instead of EXEC(string)/EXEC(@sql) string concatenation, so one cached plan is reused across every distinct value."),
 new RuleDefinition(SarifRuleCatalog.NonPersistedComputedColumnRuleId, "A computed column with is_persisted = 0 (sys.computed_columns) - its definition is recomputed from the base row on every read that touches it, independent of whether that definition calls a UDF at all. Catalog-only structural fact, never fires on a PERSISTED computed column regardless of whether it's also indexed.", "Mark the computed column PERSISTED so its definition isn't recomputed from the base row on every read that touches it."),
 new RuleDefinition(SarifRuleCatalog.SelfReferencingDmlRuleId, "An INSERT/UPDATE/DELETE/MERGE whose own read side (a self-join, a WHERE/SET subquery, or a view over the same base table) also names the exact table it writes to - oracle-confirmed to force extra defensive plan work (an Eager Spool for INSERT/DELETE, an extra Sort for UPDATE ... FROM/MERGE) that an otherwise-identical statement reading a different table never pays."),
 new RuleDefinition(SarifRuleCatalog.TemporalTableHistoryIndexGapRuleId, "A system-versioned temporal table's CURRENT side carries a nonclustered index with no structurally matching index (same key columns, same order) on its HISTORY side - oracle-confirmed that FOR SYSTEM_TIME AS OF/BETWEEN rewrites to a UNION ALL of the two tables, so a predicate that seeks the current-table branch via this index degrades to a full scan of the history-table branch. PRIMARY KEY/UNIQUE-constraint indexes are never compared - the engine itself forbids either constraint on a temporal history table.", "Create a structurally matching nonclustered index (same key columns, same order) on the HISTORY table to mirror the one on the CURRENT table."),
 new RuleDefinition(SarifRuleCatalog.ModuleCompileFlagRuleId(ModuleCompileFlagFindingKind.RecompilesEveryCall), "The module was authored WITH RECOMPILE (sys.sql_modules.is_recompiled) - every execution compiles a fresh plan and discards it immediately rather than caching it, so the module's own cost never accumulates in the plan cache at all, invisible to any monitoring that reads sys.dm_exec_cached_plans/sys.dm_exec_query_stats."),
 new RuleDefinition(SarifRuleCatalog.ModuleCompileFlagRuleId(ModuleCompileFlagFindingKind.TableValuedFunctionReturnUsesDatabaseCollation), "A non-schema-bound table-valued function's own RETURNS @t TABLE(...) declares a character-typed column with no explicit COLLATE clause, so its collation was implicitly resolved against the CURRENT database's default collation at CREATE/ALTER time and baked in (sys.sql_modules.uses_database_collation) - a later ALTER DATABASE ... COLLATE silently leaves the function's already-compiled return shape disagreeing with the database's new default. Schema-bound modules are excluded from this finding: oracle-confirmed that schema-binding sets this flag unconditionally regardless of whether the module touches string data at all, so it carries no differentiating signal there.", "Add an explicit COLLATE clause to the table-valued function's own RETURNS TABLE column declaration instead of relying on the database's default collation at CREATE/ALTER time."),
 new RuleDefinition(SarifRuleCatalog.WindowFrameRuleId(WindowFrameFindingKind.ExplicitRangeFrame), "A window function's OVER clause uses an explicit RANGE frame - oracle-confirmed to cost materially more CPU at the Window Spool operator than the equivalent ROWS frame (peer-group value comparison vs. plain physical-offset counting), though both compile to the same Window Spool physical operator, not an on-disk-vs-not distinction.", "Use an explicit ROWS frame instead of RANGE where peer-group semantics aren't actually needed - it costs materially less CPU at the Window Spool operator."),
 new RuleDefinition(SarifRuleCatalog.WindowFrameRuleId(WindowFrameFindingKind.ImplicitDefaultRangeFrame), "A window function's OVER clause has an ORDER BY but no explicit frame clause at all - T-SQL silently defaults this to RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, oracle-confirmed to carry the identical measured cost as an explicit RANGE frame, invisible in the source text.", "Add an explicit ROWS frame instead of relying on the implicit default RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW."),
 new RuleDefinition(SarifRuleCatalog.WaitForRuleId, "WAITFOR DELAY/WAITFOR TIME holds the calling worker thread idle for the full delay/until-time - a documented, unconditional cost contributing to worker-pool exhaustion under load, and (inside an open transaction) extended lock hold duration."),
 new RuleDefinition(SarifRuleCatalog.ViewOrderingRuleId(ViewOrderingFindingKind.TopPercentOrderByNeverLimits), "A view/inline TVF's own outermost query uses TOP (100) PERCENT ... ORDER BY - oracle-confirmed provably meaningless: 100 PERCENT never excludes a row, so the ORDER BY exists purely to satisfy T-SQL's own view-ordering grammar rule (Msg 1033) and is not guaranteed to any consumer that doesn't apply its own ORDER BY."),
 new RuleDefinition(SarifRuleCatalog.ViewOrderingRuleId(ViewOrderingFindingKind.OrderByNotGuaranteedToConsumer), "A view/inline TVF's own outermost query uses a genuinely row-limiting TOP (N) or OFFSET ... FETCH together with ORDER BY - the ORDER BY does decide which rows survive, but the FINAL output order is still not guaranteed to a consumer that doesn't apply its own ORDER BY, oracle-observed to sometimes still appear ordered purely as a plan-shape coincidence.", "Apply an explicit ORDER BY in the consuming query - the view/inline TVF's own ORDER BY decides which rows survive TOP/OFFSET-FETCH but doesn't guarantee the final output order to a consumer that doesn't order it itself."),
 new RuleDefinition(SarifRuleCatalog.TransactionHygieneRuleId, "A BEGIN TRANSACTION reaches a RETURN/THROW, or the natural end of the module body, on some statically reachable path with no intervening COMMIT/ROLLBACK - oracle-confirmed directly: SQL Server itself raises Msg 266 (\"Transaction count after EXECUTE indicates a mismatching number of BEGIN and COMMIT statements\") and leaves the calling session's @@TRANCOUNT elevated by one the instant such a procedure returns, holding that transaction's locks indefinitely.", "Ensure every RETURN/THROW path, and the natural end of the module body, is preceded by a matching COMMIT or ROLLBACK for every BEGIN TRANSACTION."),
 new RuleDefinition(SarifRuleCatalog.CompositeIndexLeadingColumnRuleId, "A real composite index's leading key column is never bound anywhere in the statement while the query genuinely constrains one of its NON-leading key columns - a composite index is a single B-tree keyed first by its leading column, so with no bound on that column this specific index cannot be seek-used for this predicate at all. Only fires when no OTHER usable index on the table leads with the same violating column either, so a table with a real alternative seek path is never flagged."),
 new RuleDefinition(SarifRuleCatalog.MissingStatisticsRuleId, "A predicate resolves to a real base table column that no statistic (single-column, or a multi-column statistic with this column as its own leading key) covers, while the connected database has automatic statistics creation turned off - the engine cannot create one on its own for this predicate. A non-leading occurrence of the column in a multi-column statistic does not count as coverage (oracle-confirmed: the engine still auto-creates its own single-column statistic for such a column when auto-create is on).", "Create a statistic covering this column, or turn AUTO_CREATE_STATISTICS back on for the database."),
 new RuleDefinition(SarifRuleCatalog.IndexHintRuleId(IndexHintFindingKind.IndexDoesNotExist), "An INDEX(...) table hint names an index that does not exist in the catalog for this table - oracle-confirmed a hard compile error (Msg 308) every time this statement runs, not a silently-ignored hint.", "Correct the INDEX(...) hint to name a real index that exists in the catalog, or remove the hint."),
 new RuleDefinition(SarifRuleCatalog.IndexHintRuleId(IndexHintFindingKind.HintedIndexNotSeekable), "An INDEX(...) table hint names a real index whose own leading key column is never bound anywhere in the statement - the hint forces the engine to use this specific index (not merely suggest it), and with no bound on the leading key the engine cannot descend its B-tree to a useful starting point, oracle-confirmed to degrade the forced access path to a full index scan.", "Bind the hinted index's own leading key column in the statement, or hint a different index whose leading column is actually usable."),
 new RuleDefinition(SarifRuleCatalog.SessionDateSettingRuleId(SessionDateSettingKind.DateFormat), "SET DATEFORMAT appears in this module's own body - oracle-confirmed the identical ambiguous string date literal ('03/04/2026') resolves to a different real date (March 4 vs. April 3) depending purely on which DATEFORMAT value was set first in the session, independent of the caller's own settings.", "Use an unambiguous ISO date literal format (YYYYMMDD) instead of relying on SET DATEFORMAT to resolve an ambiguous string date."),
 new RuleDefinition(SarifRuleCatalog.SessionDateSettingRuleId(SessionDateSettingKind.DateFirst), "SET DATEFIRST appears in this module's own body - oracle-confirmed DATEPART(weekday, ...) for a fixed real date returns a different ordinal depending purely on which DATEFIRST value was set first in the session.", "Avoid relying on the session's own SET DATEFIRST value for weekday math - use a DATEFIRST-independent computation instead."),
 new RuleDefinition(SarifRuleCatalog.CartesianJoinRuleId(CartesianJoinKind.CommaJoin), "A legacy comma-join (FROM A, B) with no predicate anywhere in the statement - no ON clause, no WHERE clause - connecting the two tables at all: a true cartesian product, the classic 'forgot the join condition' defect.", "Add an explicit join predicate (ON clause or WHERE condition) connecting the two tables."),
 new RuleDefinition(SarifRuleCatalog.CartesianJoinRuleId(CartesianJoinKind.ExplicitCrossJoin), "An explicit CROSS JOIN with no predicate anywhere in the statement connecting the two tables - the author wrote CROSS JOIN, self-documenting a deliberate cartesian product, but this is still worth surfacing since an accidentally-left CROSS JOIN is a real, if less common, mistake.", "Confirm the CROSS JOIN is deliberate; if not, add an explicit join predicate connecting the two tables."),
 new RuleDefinition(SarifRuleCatalog.UndersizedDeclarationRuleId(UndersizedDeclarationSite.TableColumn), "A real table column is declared with a string/binary length of 1 or 2 - almost always a truncated-from-a-larger-source mistake or a leftover single-character-flag placeholder that later grew real string content. Advisory only, no compared column needed - distinct from the under-length-vs-compared-column stream."),
 new RuleDefinition(SarifRuleCatalog.UndersizedDeclarationRuleId(UndersizedDeclarationSite.Declaration), "A DECLARE'd local variable or a procedure/function formal parameter is declared with a string/binary length of 1 or 2 - the same advisory-only, no-compared-column-needed claim as the table-column sibling."),
 new RuleDefinition(SarifRuleCatalog.TruncateSwallowedRuleId, "TRUNCATE TABLE sits inside a TRY block whose CATCH block never THROWs/RAISERRORs anywhere in its own statement tree - oracle-confirmed a real TRUNCATE failure (e.g. an enforced FK reference, Msg 4712) is silently swallowed here, with execution continuing as if the TRUNCATE had succeeded and no error reaching the caller. TRY with no matching CATCH at all is a hard parse error (Msg 102) and can never occur in valid T-SQL, correcting this item's own original framing.", "Add a THROW or RAISERROR inside the CATCH block so a real TRUNCATE failure doesn't get silently swallowed."),
 new RuleDefinition(SarifRuleCatalog.UnindexedTempTableUsageRuleId(UnindexedTempTableUsageKind.JoinOperand), "A SELECT...INTO #temp table is later used as a JOIN operand in the same batch/procedure scope, but no index was ever created on it - oracle-confirmed this forces a full scan/Hash Match of the entire temp table, with no seek alternative possible at all without an index.", "Create an index on the #temp table before using it as a JOIN operand."),
 new RuleDefinition(SarifRuleCatalog.UnindexedTempTableUsageRuleId(UnindexedTempTableUsageKind.FilteredInWhere), "A SELECT...INTO #temp table is later filtered by a WHERE predicate in the same batch/procedure scope, but no index was ever created on it - the same no-seek-possible cost as the JOIN-operand sibling.", "Create an index on the #temp table covering the WHERE-filtered column(s)."),
 new RuleDefinition(SarifRuleCatalog.OutputParameterRuleId, "A procedure's own OUTPUT parameter is not assigned on some statically reachable path (a RETURN, or the natural end of the body) - oracle-confirmed a caller's own variable is left completely unchanged by the call on that path (not reset to NULL), so a reused caller variable can silently carry stale data from a previous, unrelated call.", "Assign the OUTPUT parameter on every statically reachable path, including RETURN and the natural end of the body."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.PageVerifyNotChecksum), "PAGE_VERIFY is not CHECKSUM - silent storage-level page corruption can go undetected until a much later, harder-to-diagnose failure.", "Set PAGE_VERIFY to CHECKSUM."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.AutoShrinkOn), "AUTO_SHRINK is ON - a well-known, severe anti-pattern: constant fragmentation churn as the engine shrinks the file and the workload immediately re-grows it.", "Turn AUTO_SHRINK OFF."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.AutoCloseOn), "AUTO_CLOSE is ON - the database's connection/buffer-pool state is torn down after the last connection closes and rebuilt from scratch on the next one.", "Turn AUTO_CLOSE OFF."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.TargetRecoveryTimeUnset), "TARGET_RECOVERY_TIME is 0 (disabled) - indirect checkpoint is off; confirmed directly against a freshly created database on the same engine that the modern default is 60 seconds, not 0.", "Set TARGET_RECOVERY_TIME explicitly instead of leaving it at 0 (disabled)."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.QueryStoreNotReadWrite), "Query Store is not actively running (actual state is not READ_WRITE) - informational: a real operational choice, not a universal anti-pattern."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.QueryStoreCaptureModeNotAuto), "Query Store is running with a capture mode other than AUTO - informational: ALL is a deliberate, real choice some teams prefer for active troubleshooting."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.AutoCreateStatisticsOff), "AUTO_CREATE_STATISTICS is OFF - the optimizer can no longer create a missing single-column statistics object on demand, so a predicate against an unstatted column compiles against a guessed cardinality instead of a real histogram.", "Turn AUTO_CREATE_STATISTICS ON so the optimizer can create a missing single-column statistics object on demand."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.AutoUpdateStatisticsOff), "AUTO_UPDATE_STATISTICS is OFF - statistics never refresh as the underlying data changes, so every plan compiled against them drifts further from reality the longer the database runs.", "Turn AUTO_UPDATE_STATISTICS ON so statistics keep refreshing as the underlying data changes."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.CompatibilityLevelBehindEngineDefault), "The database's compatibility level is behind the connected engine instance's own current default (read live from the model system database, not a hardcoded version-number mapping) - it is silently kept on an older cardinality estimator and query-optimizer behavior nobody chose on purpose.", "Raise the database's compatibility level to the connected engine instance's own current default."),
 new RuleDefinition(SarifRuleCatalog.DatabaseConfigurationRuleId(DatabaseConfigurationFindingKind.SpatialPersistedComputedColumnDisabledOnCompatibilityLevelChange), "SQL Server's own sys.dm_db_objects_disabled_on_compatibility_level_change DMV reports that this index depends on a persisted computed column using a spatial UDT method and will be disabled at the connected instance's current default compatibility level.", "Replace the persisted computed-column spatial expression or plan to rebuild the affected index after validating the compatibility-level change."),
 new RuleDefinition(SarifRuleCatalog.TempTableExecShapeColumnCountMismatchRuleId, "INSERT INTO #temp EXEC proc, where the executed proc's real, engine-described result-set column count differs from #temp's own declared column count - INSERT ... EXEC binds purely by position, so this always raises a hard runtime error (Msg 213/8164) every time the statement executes, live-verified against sys.dm_exec_describe_first_result_set (compile-only).", "Make #temp's declared column list match the executed procedure's real result-set column count exactly - INSERT ... EXEC binds purely by position."),
 new RuleDefinition(SarifRuleCatalog.TempTableExecShapeColumnTypeMismatchRuleId, "INSERT INTO #temp EXEC proc, where column counts match but at least one position's type risks silent data loss between the executed proc's real, engine-described column type and #temp's own declared column type - a per-column WriteLossKind classification, live-verified against sys.dm_exec_describe_first_result_set (compile-only).", "Match #temp's declared column types to the executed procedure's real result-set column types at each position."),
 new RuleDefinition(SarifRuleCatalog.PartialCompositeForeignKeyJoinRuleId, "A JOIN equates some but not all of a real composite foreign key's column pairs - the omitted column(s) let one parent row match more than one child row than the declared relationship allows, silently multiplying rows through the join. A correctness and plan defect, not a lost seek.", "Equate every column pair of the composite foreign key in the JOIN, not just some of them."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.QuotedIdentifierOffBlocksIndexedFeature), "The module was compiled under QUOTED_IDENTIFIER OFF (sys.sql_modules.uses_quoted_identifier) while its own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan.", "Compile the module under QUOTED_IDENTIFIER ON so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.NumericRoundabortOnBlocksIndexedFeature), "An explicit SET NUMERIC_ROUNDABORT ON in a module whose own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan.", "Remove or turn off SET NUMERIC_ROUNDABORT ON so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.AnsiNullsOffBlocksIndexedFeature), "The module was compiled under ANSI_NULLS OFF (sys.sql_modules.uses_ansi_nulls) while its own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan.", "Compile the module under ANSI_NULLS ON so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.AnsiWarningsOffBlocksIndexedFeature), "An explicit SET ANSI_WARNINGS OFF in a module whose own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan.", "Remove or turn off SET ANSI_WARNINGS OFF so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.ConcatNullYieldsNullOffBlocksIndexedFeature), "An explicit SET CONCAT_NULL_YIELDS_NULL OFF in a module whose own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan.", "Remove or turn off SET CONCAT_NULL_YIELDS_NULL OFF so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.SetOptionRuleId(SetOptionFindingKind.AnsiPaddingOffBlocksIndexedFeature), "An explicit SET ANSI_PADDING OFF in a module whose own body touches a filtered index or an indexed view - the optimizer cannot use either under this setting, so it silently falls back to a base-table/heap scan. Distinct from the AnsiPaddingMismatch finding, which is a data-semantics claim about which rows a LIKE pattern matches, not a plan-shape one.", "Remove or turn off SET ANSI_PADDING OFF so the optimizer can use the filtered index or indexed view."),
 new RuleDefinition(SarifRuleCatalog.ParameterReassignmentPredicateRuleId, "A formal parameter is reassigned (SET/SELECT) on every statically reachable path before a later predicate use of the same name - the optimizer's compile-time SNIFFED value (from the caller's original argument) is provably stale by the time this predicate executes, unlike a plain DECLARE'd local (which was never sniffable at all). The predicate is still fully sargable; only the row-count ESTIMATE built from the sniffed value is at risk. Suppressed when the statement carries OPTION (RECOMPILE) or the procedure is WITH RECOMPILE.", "Add OPTION (RECOMPILE) to the statement, or WITH RECOMPILE to the procedure, so the estimate isn't built from a compile-time-stale sniffed value."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricLineTooLongRuleId, "A physical source line exceeds the configured maximum character length. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricModuleTooLongRuleId, "A module (or, in file-mode, a source file) exceeds the configured maximum line count. Purely a maintainability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricRoutineTooLongRuleId, "A procedure/function/trigger body exceeds the configured maximum line count. Purely a maintainability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricTooManyParametersRuleId, "A procedure/function declares more formal parameters than the configured maximum. Purely a maintainability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricNestingTooDeepRuleId, "An IF/WHILE/TRY nests more than the configured maximum depth inside a routine. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricTooManyConditionalOperatorsRuleId, "A single IF/WHILE condition chains more AND/OR operators than the configured maximum. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricTooManyCaseBranchesRuleId, "A single CASE expression has more WHEN branches than the configured maximum. Purely a maintainability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.CodeMetricCaseBranchTooLongRuleId, "A single CASE WHEN branch's result expression spans more lines than the configured maximum. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingTabCharacterUsedRuleId, "A literal tab character appears in the source text. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingMultipleStatementsOnSameLineRuleId, "Two or more statements in the same block start on the same physical source line. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingMultipleDeclarationsOnSameLineRuleId, "Two or more variables in the same DECLARE are declared on the same physical source line. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingMissingBeginEndBlockRuleId, "An IF/WHILE/ELSE body is a single statement with no BEGIN...END - a later statement added here without braces silently falls outside the conditional. Purely a maintainability risk - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingSingleLineConditionalBodyRuleId, "An IF/WHILE/ELSE body is a single unbraced statement sharing its own keyword's line - visually easy to misread. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingDanglingStatementAfterUnbracedBodyRuleId, "A statement immediately follows an unbraced IF/WHILE's single-statement body, visually appearing to still be inside the conditional/loop when it is not. The statement's own behavior is unaffected - only a future edit relying on the misleading visual shape is at risk."),
 new RuleDefinition(SarifRuleCatalog.FormattingIfImmediatelyFollowingPriorBlockEndRuleId, "An IF immediately follows the closing END of a prior braced IF on the same line - easy to misread as an ELSE IF continuation when it is really a separate, unconditional statement. The statement's own behavior is unaffected - only a future edit relying on the misleading visual shape is at risk."),
 new RuleDefinition(SarifRuleCatalog.FormattingRedundantParenthesesRuleId, "A parenthesized expression whose parentheses do not change grouping or precedence at all. Purely a readability signal - no query result or plan is affected."),
 new RuleDefinition(SarifRuleCatalog.FormattingMissingFileHeaderCommentRuleId, "A module's own definition does not begin with a comment before its first real statement. Purely advisory - T-SQL modules carry no universal file-header convention the way application source files do."),
 new RuleDefinition(SarifRuleCatalog.NamingReservedKeywordAsIdentifierRuleId, "A declared identifier is spelled identically to a reserved T-SQL keyword, forcing every future reference to remember to bracket- or quote-delimit it.", "Rename the identifier to avoid a reserved T-SQL keyword, or accept that it must always be bracket/quote-delimited."),
 new RuleDefinition(SarifRuleCatalog.NamingSpPrefixOnUserRoutineRuleId, "A user-defined procedure or function is named with the \"sp_\" prefix, reserved by convention for system-shipped procedures - SQL Server searches the master database first for any unqualified call, adding lookup overhead and risking a silent collision with a real system procedure of the same name.", "Rename the routine to drop the sp_ prefix, reserved for system-shipped procedures."),
 new RuleDefinition(SarifRuleCatalog.NamingUnqualifiedCreateRuleId, "A CREATE/ALTER for a schema-scoped procedure/function/view names it with no explicit schema qualifier - the object's real owning schema then depends on the connecting principal's own default schema at deployment time.", "Qualify the CREATE/ALTER statement with the object's real intended schema explicitly."),
 new RuleDefinition(SarifRuleCatalog.NamingRedundantTypeQualifierRuleId, "A data type reference carries a redundant \"dbo.\" schema qualifier that adds nothing and couples the declaration to a schema it does not need to name.", "Drop the redundant \"dbo.\" schema qualifier from the data type reference."),
 new RuleDefinition(SarifRuleCatalog.DeadCodeUnreachableCodeRuleId, "A statement structurally can never execute - it follows a statement that always ends the enclosing routine on every path (RETURN/THROW, or an IF/TRY-CATCH whose every branch itself always ends it).", "Delete the unreachable statement, or fix the preceding logic if reaching it was actually intended."),
 new RuleDefinition(SarifRuleCatalog.DeadCodeUnusedLabelRuleId, "A label target that no GOTO anywhere in the same routine ever jumps to.", "Delete the unused label, or add the GOTO that was meant to jump to it."),
 new RuleDefinition(SarifRuleCatalog.DeadCodeUnusedLocalVariableRuleId, "A DECLARE'd local variable is never read anywhere after being declared - only ever assigned, or never referenced at all.", "Delete the unused local variable, or add the read that was meant to use it."),
 new RuleDefinition(SarifRuleCatalog.DeadCodeUnusedParameterRuleId, "A non-OUTPUT formal parameter is never referenced anywhere in the routine body.", "Delete the unused parameter, or add the reference that was meant to use it."),
 new RuleDefinition(SarifRuleCatalog.DeadCodeRedundantJumpRuleId, "A GOTO whose target label is the very next statement in the same straight-line sequence - jumping to exactly where control flow would already go.", "Delete the GOTO - control flow already reaches the same place without it."),
 new RuleDefinition(SarifRuleCatalog.DuplicationCommentedOutCodeRuleId, "A comment's own stripped content reparses cleanly as a plausible T-SQL statement or batch - not prose that merely mentions SQL keywords.", "Delete the commented-out code - version control already preserves its history."),
 new RuleDefinition(SarifRuleCatalog.DuplicationDuplicatedStringLiteralRuleId, "The same non-trivial string literal appears three or more times within one module - a magic value that should be a variable or constant instead.", "Extract the repeated string literal into a variable or constant instead of repeating it."),
 new RuleDefinition(SarifRuleCatalog.DuplicationSingleIterationLoopRuleId, "A WHILE loop's own body unconditionally reaches a BREAK/RETURN/THROW on every path through the first iteration - it can never loop a second time.", "Replace the loop with plain straight-line code (or an IF), since it can never execute a second iteration."),
 new RuleDefinition(SarifRuleCatalog.DuplicationSelfAssignmentRuleId, "A pure no-op assignment: a variable or UPDATE column assigned to itself.", "Delete the no-op self-assignment."),
 new RuleDefinition(SarifRuleCatalog.DuplicationIdenticalBinaryOperandsRuleId, "The identical expression appears on both sides of a comparison, AND/OR, or a self-referential arithmetic operator - always the same value, a tautology, or a fixed degenerate result."),
 new RuleDefinition(SarifRuleCatalog.DuplicationRepeatedUnaryOperatorRuleId, "The same unary operator (NOT, unary minus, bitwise NOT) is applied twice in a row - always simplifiable to a single application or none.", "Simplify to a single application of the operator (or remove it entirely if the double application cancels out)."),
 new RuleDefinition(SarifRuleCatalog.DuplicationNegatedComparisonAsOppositeRuleId, "A negated comparison is written instead of its provably equivalent opposite operator - a readability suggestion, not a correctness claim.", "Rewrite the negated comparison using its provably equivalent opposite operator."),
 new RuleDefinition(SarifRuleCatalog.DuplicationDuplicateSiblingConditionRuleId, "A later branch in an IF/ELSE IF chain or CASE expression repeats an earlier sibling's own condition verbatim - the later branch can never be reached.", "Remove the later branch - it can never be reached - or fix its condition if a different check was intended."),
 new RuleDefinition(SarifRuleCatalog.DuplicationIdenticalBranchBodiesRuleId, "Two (but not all) branches of a conditional structure have an identical body or result - either the conditional is partly pointless, or a copy-paste mistake left one branch matching another."),
 new RuleDefinition(SarifRuleCatalog.DuplicationAllBranchesIdenticalRuleId, "Every branch of a conditional structure, including its ELSE, has an identical body or result - the structure produces the same outcome no matter which branch is taken.", "Remove the conditional structure - it produces the same outcome no matter which branch is taken."),
 new RuleDefinition(SarifRuleCatalog.DuplicationRedundantAndConditionRuleId, "Two conjuncts of one AND-combined condition compare the same operand against numeric bounds where one bound's range is already a subset of the other's - the looser bound adds nothing.", "Drop the looser numeric bound - it adds nothing since the other conjunct's range is already a subset."),
 new RuleDefinition(SarifRuleCatalog.DuplicationMutuallyExclusiveAndConditionRuleId, "Two conjuncts of one AND-combined condition compare the same operand against numeric bounds whose ranges cannot both hold at once - the condition can never be true."),
 new RuleDefinition(SarifRuleCatalog.DuplicationCollapsibleNestedIfRuleId, "An IF with no ELSE whose entire body is a single nested IF, also with no ELSE - semantically identical to one IF combining both conditions with AND.", "Combine the two conditions with AND into a single IF, replacing the nested pair."),
 new RuleDefinition(SarifRuleCatalog.DuplicationNestedConditionalExpressionRuleId, "An IIF call is nested inside another IIF call's own THEN or ELSE branch - T-SQL's equivalent of a nested ternary expression."),
 new RuleDefinition(SarifRuleCatalog.DuplicationAlwaysTrueOrFalseLiteralComparisonRuleId, "A comparison between two literal values (never a column or variable) is provable at parse time regardless of any row's real data - the predicate is dead weight or can never match."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxTaskCommentTodoRuleId, "A comment contains an untracked \"TODO\" marker."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxTaskCommentFixmeRuleId, "A comment contains an untracked \"FIXME\" marker."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxNonAnsiComparisonOperatorRuleId, "A non-ANSI comparison operator (!=, !<, !>) is used instead of the ANSI-standard spelling.", "Use the ANSI-standard comparison operator (e.g. <> instead of !=) instead of the non-ANSI spelling."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxEqualsNullComparisonRuleId, "\"= NULL\" never matches any row under the default ANSI_NULLS ON session setting, including a genuinely NULL value - use \"IS NULL\" instead.", "Use IS NULL instead of = NULL."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxNotEqualsNullComparisonRuleId, "\"<> NULL\"/\"!= NULL\" never matches any row under the default ANSI_NULLS ON session setting - use \"IS NOT NULL\" instead.", "Use IS NOT NULL instead of <> NULL / != NULL."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxLikeWithNoWildcardRuleId, "A LIKE pattern contains no wildcard character - behaviorally equivalent to a plain \"=\" comparison.", "Use a plain = comparison instead of LIKE when the pattern has no wildcard."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxLegacySystemCompatibilityViewRuleId, "A reference to a pre-SQL-Server-2005 system compatibility view, retained only for backward compatibility and missing columns/rows the real sys.* catalog view exposes.", "Reference the real sys.* catalog view instead of the legacy compatibility view."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxTableHintWithoutWithRuleId, "A table hint is written without the WITH keyword - a deprecated syntax form still accepted by the parser and engine.", "Add the WITH keyword before the table hint."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxNumberedProcedureDefinitionRuleId, "A procedure is defined as a numbered-procedure-group member - a deprecated T-SQL feature still accepted by the parser and engine.", "Define separate, individually named procedures instead of a numbered-procedure-group member."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxNumberedProcedureExecutionRuleId, "A procedure is invoked by its numbered-procedure-group number.", "Invoke the procedure by its real name instead of its numbered-group number."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxStringLiteralColumnAliasRuleId, "A column alias is written as a string literal instead of a real identifier - a deprecated aliasing form still accepted by the parser and engine.", "Alias the column with a real identifier instead of a string literal."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxRemovedSecurityStoredProcedureRuleId, "A legacy security-administration system stored procedure is invoked, superseded by CREATE LOGIN/CREATE USER/ALTER ROLE - some names in this family are already fully removed from current SQL Server versions.", "Use CREATE LOGIN/CREATE USER/ALTER ROLE instead of the legacy security-administration stored procedure."),
 new RuleDefinition(SarifRuleCatalog.DeprecatedSyntaxDeprecatedSetRowcountRuleId, "SET ROWCOUNT is deprecated - use TOP (n) instead; Microsoft documents it as not honored by INSERT/UPDATE/DELETE in a future release.", "Use TOP (n) instead of SET ROWCOUNT."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeInsertWithoutColumnListRuleId, "An INSERT with no explicit column list silently breaks if the target table's column order/count ever changes.", "Add an explicit column list to the INSERT."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeOrdinalOrderByRuleId, "An ORDER BY references a SELECT-list position by ordinal number - silently wrong if the SELECT list's own column order changes.", "Reference the ORDER BY column by name instead of its SELECT-list ordinal position."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeTopWithoutOrderByRuleId, "A TOP row-limiting clause has no ORDER BY anywhere in the query - Microsoft's own documentation states which rows come back is not guaranteed in this shape.", "Add an explicit ORDER BY to the query."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeTableWithNoPrimaryKeyRuleId, "A base table has no PRIMARY KEY constraint - no engine-enforced row uniqueness.", "Add a PRIMARY KEY constraint to the table."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeMissingSetNocountOnRuleId, "A procedure or trigger never sets NOCOUNT ON - every DML statement it runs sends a client-visible rowcount message.", "Add SET NOCOUNT ON at the top of the procedure or trigger."),
 new RuleDefinition(SarifRuleCatalog.StatementShapeBareSelectStarRuleId, "A bare SELECT * couples the query to the target's current column set.", "Name the columns explicitly instead of using SELECT *."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskCursorFetchColumnCountMismatchRuleId, "A cursor FETCH INTO variable count doesn't match its own cursor's defining SELECT column count - always fails at runtime.", "Match the FETCH INTO variable list's count to the cursor's own defining SELECT column count."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskEmptyCatchBlockRuleId, "A CATCH block has no statements - every error reaching it is silently swallowed.", "Add real error handling (at minimum a THROW or logging) inside the CATCH block instead of leaving it empty."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskTriggerEmitsOutputRuleId, "A trigger emits a result set or message back to whatever connection fired the DML, not the calling application.", "Remove the result set or message the trigger emits - it reaches whatever connection fired the DML, not the calling application."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskDirtyReadIsolationHintRuleId, "NOLOCK/READUNCOMMITTED allows dirty reads and can miss or double-count rows during a concurrent page split.", "Avoid NOLOCK/READUNCOMMITTED where dirty reads or missed/double-counted rows during a concurrent page split are not acceptable."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskDuplicatedCallArgumentRuleId, "The same non-literal expression is passed as two different arguments to the same call."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskLegacyIdentityIntrinsicRuleId, "@@IDENTITY returns the last identity value inserted in this session across any table/scope - prefer SCOPE_IDENTITY().", "Use SCOPE_IDENTITY() instead of @@IDENTITY."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskGotoUsageRuleId, "A GOTO statement - unrestricted jumps make control flow harder to follow, and this tool's own dead-code analysis declines entirely for a routine that contains one.", "Restructure the control flow to avoid GOTO - unrestricted jumps also disable this tool's own dead-code analysis for the routine."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskCaseExpressionMissingElseRuleId, "A simple CASE expression has no ELSE - an input value matching none of the WHEN values silently evaluates to NULL, no error raised.", "Add an explicit ELSE branch to the CASE expression."),
 new RuleDefinition(SarifRuleCatalog.ControlFlowRiskNonDeterministicCaseInputRuleId, "A non-deterministic function (NEWID/RAND/CRYPT_GEN_RANDOM) is used as a simple CASE expression's input - oracle-confirmed to be re-evaluated separately per WHEN comparison, not once, making every WHEN branch effectively unreachable.", "Assign the non-deterministic function's result to a variable first, then use the variable as the CASE input, instead of calling the function directly as the CASE input."),
 new RuleDefinition(SarifRuleCatalog.SecurityRuleId(SecurityFindingKind.HardCodedCredential), "A credential-suggestive-named variable/parameter is assigned a literal string value directly in source text - keep credentials in a secrets store or external configuration.", "Keep the credential in a secrets store or external configuration instead of hard-coding it in source text."),
 new RuleDefinition(SarifRuleCatalog.SecurityRuleId(SecurityFindingKind.HardCodedIpAddress), "A string literal contains a hardcoded, non-benign IPv4 address - an environment-specific detail embedded in code.", "Move the IP address into configuration instead of hard-coding it in source text."),
 new RuleDefinition(SarifRuleCatalog.SecurityRuleId(SecurityFindingKind.WeakHashAlgorithm), "A HASHBYTES call names a cryptographically broken/deprecated algorithm (MD2/MD4/MD5/SHA/SHA1) - prefer SHA2_256/SHA2_512.", "Use HASHBYTES with SHA2_256 or SHA2_512 instead of a broken/deprecated algorithm."),
 new RuleDefinition(SarifRuleCatalog.SecurityRuleId(SecurityFindingKind.WeakHashAlgorithmInSensitiveContext), "A HASHBYTES call names a weak/deprecated algorithm in what looks like a security-sensitive context (a credential-named operand, or a direct comparison).", "Use HASHBYTES with SHA2_256 or SHA2_512 instead of a weak/deprecated algorithm, especially in a security-sensitive context."),
 new RuleDefinition(SarifRuleCatalog.SecurityRuleId(SecurityFindingKind.UnprovableDynamicSqlText), "A dynamic SQL call site's assembled text depends on a variable/parameter/expression this tool cannot trace - it cannot be shown, from the code alone, to be free of runtime/external influence."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.HeapWithNonclusteredIndexes), "A table has no clustered index anywhere but carries one or more nonclustered indexes - each one points back to its base row with an 8-byte RID instead of the clustering key, and that RID can change under heap maintenance (forwarded-row pointers).", "Add a clustered index to the table instead of leaving it a heap."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.HeapWithNonclusteredPrimaryKey), "A table has no clustered index anywhere because its own PRIMARY KEY constraint is declared NONCLUSTERED - the sharper sibling of the general heap-with-nonclustered-indexes finding.", "Declare the PRIMARY KEY constraint CLUSTERED instead of NONCLUSTERED."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.NonUniqueClusteredIndex), "A CLUSTERED index is not unique - the engine adds a hidden 4-byte uniquifier to every duplicate-keyed row, widening the key every nonclustered index on the table also carries in its own leaf rows.", "Make the clustered index's key unique (or add a uniquifying column) so the engine doesn't add its own hidden 4-byte uniquifier."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.WideClusteredKey), "A CLUSTERED index's key is wide (more than 3 key columns, or more than 16 estimated bytes) - every nonclustered index on the table carries a full copy of this key in every leaf row.", "Narrow the clustered index's key to fewer/smaller columns - every nonclustered index carries a full copy of it."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.RandomClusteredKeyGuidDefault), "A CLUSTERED index leads on a uniqueidentifier column defaulted to NEWID() - genuinely random insert order into a clustered B-tree causes severe page splits and fragmentation; NEWSEQUENTIALID() avoids this.", "Default the uniqueidentifier column to NEWSEQUENTIALID() instead of NEWID()."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.DuplicateIndex), "Two active indexes on the same table share an identical key list, uniqueness, and index kind - exact duplicates; one is pure write amplification and wasted space with no query benefit.", "Drop one of the two exact-duplicate indexes."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.SubsumedIndex), "An active index's key list is a leading-column prefix of another index's own key list, with its INCLUDE columns already covered by the wider index - the narrower index is redundant.", "Drop the narrower, redundant index - the wider index already covers it."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.UnindexedForeignKey), "A real FOREIGN KEY constraint's own parent-side column set has no active index leading on it - every parent-side DELETE/UPDATE forces a referential-integrity scan of the child table, and every join along the relationship has no seek path.", "Add an index leading on the foreign key's parent-side column set."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.DisabledIndex), "ALTER INDEX ... DISABLE was left in place - unusable by the engine until rebuilt, but still occupies catalog metadata and blocks a same-named CREATE INDEX.", "Rebuild the disabled index to make it usable again, or drop it if it's no longer needed."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.HypotheticalIndex), "A Database Engine Tuning Advisor/missing-index-wizard hypothetical index (sys.indexes.is_hypothetical = 1) was left behind - no real data behind it, safe to drop.", "Drop the hypothetical index - it has no real data behind it."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.ManyNonclusteredIndexes), "A table carries an unusually high number of active nonclustered indexes - each one is paid for on every write; this does not identify which index is safe to drop."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.ManyKeyColumnsIndex), "A single index carries an unusually high number of key columns - every one is carried in every leaf-level lookup and update against this index.", "Reduce the number of key columns in the index to only those actually needed for seeking/ordering."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.WideTable), "A table has an unusually large column count or estimated non-LOB row width - a data-modeling signal, not a specific proven defect."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.HighNullableColumnRatio), "A table's columns are mostly nullable - often a sign of several optional sub-entities crammed into one table."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.HighStringColumnRatio), "A table's columns are mostly string-typed - often correlates with under-typed data."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.FilterColumnNotInIndex), "A filtered index's own filter predicate references a column not in its own key/INCLUDE list - the engine cannot cheaply confirm the filter still holds for a query that doesn't already carry that column, defeating the covering benefit a filtered index exists for.", "Add the filtered index's own filter column(s) to its key or INCLUDE list."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.DeprecatedLobColumnType), "A column is declared text/ntext/image - formally deprecated by Microsoft since SQL Server 2005 in favor of the MAX-length equivalent, and a future engine version may remove it entirely.", "Use the MAX-length equivalent (varchar(max)/nvarchar(max)/varbinary(max)) instead of text/ntext/image."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.TimestampColumnNaming), "A column is declared timestamp - since SQL Server 2005, rowversion is a synonym for the identical underlying type; a naming-only recommendation, not a functional deprecation.", "Use rowversion instead of timestamp - they're the identical type, but rowversion is the non-deprecated name."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.FloatOrRealIndexKeyColumn), "An index's key carries a float/real (approximate) column - IEEE-754 representation error means an equality seek/comparison against it can silently miss a value a person would call the same number.", "Avoid float/real columns as index keys, or avoid equality comparisons/seeks against them, given IEEE-754 representation error."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.NoRecomputeStatistics), "A statistics object is marked NORECOMPUTE - the engine's automatic statistics maintenance never refreshes it, so its cardinality estimate silently drifts stale as the table's data changes.", "Remove the NORECOMPUTE option so the engine's automatic statistics maintenance keeps this object refreshed."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.VariableLengthKeyColumnExceedsKeyLimit), "A varchar/nvarchar/varbinary index key column's declared max byte width exceeds the engine's key-length ceiling (900 bytes clustered, 1700 bytes nonclustered) - CREATE INDEX only warns, so the first INSERT/UPDATE that actually stores a long-enough value fails at that moment instead, silently until then.", "Shorten the column's declared max length so the index key stays under the engine's limit (900 bytes clustered, 1700 nonclustered)."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.MergeableIndexesDifferingIncludeOnly), "Two active indexes share an identical key list and sort direction but carry different, non-overlapping INCLUDE columns - mergeable into one index carrying the union at no seek cost to either original query, for less write/storage overhead than carrying both.", "Merge the two indexes into one carrying the union of their INCLUDE columns."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.ColumnstoreIndexOnDmlTargetTable), "A table carries a columnstore index and is also a direct DML target elsewhere in this codebase - lock escalation on a columnstore index happens at rowgroup granularity, not row granularity, so a single-row write inside an explicit transaction can block unrelated concurrent access to the rest of that rowgroup. Structural risk flag only; actual contention is workload-dependent."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.MonotonicClusteredKeyMissingSequentialOptimization), "A clustered index leads on an always-ascending IDENTITY column with OPTIMIZE_FOR_SEQUENTIAL_KEY not enabled - every insert lands on the same trailing page, so concurrent inserts can serialize on that page's latch. Structural risk flag only; actual contention depends on concurrent insert rate.", "Enable OPTIMIZE_FOR_SEQUENTIAL_KEY on the clustered index."),
 new RuleDefinition(SarifRuleCatalog.IndexDesignRuleId(IndexDesignFindingKind.NonAlignedPartitionedIndex), "The table is genuinely partitioned, but another active index on it is not aligned with that partitioning - either it sits on a single unpartitioned filegroup, or it shares the same partition scheme but is keyed on a different column than the table's own partitioning column. A non-aligned index cannot participate in a partition SWITCH against the table, and per-partition maintenance on it degrades to a full-index operation.", "Rebuild the index on the table's own partition scheme, keyed on the table's own partitioning column."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.LikePatternLiteral), "A LIKE predicate's pattern is a literal, not a variable - the engine leaves it unparameterized even under PARAMETERIZATION FORCED, so a workload varying only this pattern still recompiles per distinct value.", "Pass the LIKE pattern as a parameter/variable instead of a literal, or accept the per-value recompile."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.TopOrPagingLiteral), "A TOP row count or OFFSET/FETCH paging count is a literal - the engine leaves it unparameterized even under PARAMETERIZATION FORCED, so a workload varying the page size still recompiles per distinct value.", "Pass the row/page count as a parameter/variable (e.g. TOP (@N)) instead of a literal."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.SelectListLiteral), "A literal sits directly in the SELECT list - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the select-list literal as a parameter/variable instead."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.HavingLiteral), "A literal is a direct comparison operand inside a HAVING clause - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the HAVING comparand as a parameter/variable instead of a literal."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.OrderByExpressionLiteral), "A literal appears inside a compound ORDER BY expression - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the literal inside the ORDER BY expression as a parameter/variable instead."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.DoubleColonCallArgumentLiteral), "A literal argument to a TypeName::Method(...) static call (CLR UDT/spatial types) stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the static-call argument as a parameter/variable instead of a literal."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.TableSampleSizeLiteral), "A TABLESAMPLE clause's sample size is a literal - it stays unparameterized even under PARAMETERIZATION FORCED. Unlike other members of this family, this has no parameter workaround: TABLESAMPLE rejects a variable outright (Msg 497)."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.DmlOutputListLiteral), "A literal sits in a DML statement's own OUTPUT clause select list - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the OUTPUT-list literal as a parameter/variable instead."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.ConvertStyleCodeLiteral), "A CONVERT(type, expr, style) call's style-code argument is a literal - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the CONVERT style code as a parameter/variable instead of a literal."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.CheckSumArgumentLiteral), "A literal is passed directly as an argument to CHECKSUM(...) - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the CHECKSUM(...) argument as a parameter/variable instead of a literal."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.ConstantFoldableExpressionLiteral), "A constant-foldable arithmetic expression against a column parameterizes as two separate parameters instead of one folded value - the statement still parameterizes, just less optimally."),
 new RuleDefinition(SarifRuleCatalog.ForcedParameterizationRuleId(ForcedParameterizationFindingKind.GroupByExpressionLiteral), "A literal appears inside a GROUP BY expression - it stays unparameterized even under PARAMETERIZATION FORCED.", "Pass the literal inside the GROUP BY expression as a parameter/variable instead."),
 new RuleDefinition(SarifRuleCatalog.IdentityRangeRuleId(IdentityRangeFindingKind.IdentitySeedOrIncrementAnomaly), "An IDENTITY column carries a negative seed or a non-1 increment - an unusual, informational data-modeling signal, not a proven defect (schema-decidable: identical on a dev and a production copy of the same schema)."),
 new RuleDefinition(SarifRuleCatalog.IdentityRangeRuleId(IdentityRangeFindingKind.IdentityRangeNearExhaustion), "An IDENTITY column has consumed most of its declared type's representable range - once exhausted, every subsequent INSERT raises a hard arithmetic-overflow error. Data-state-decidable: meaningful only against a production-shaped target, never a dev database.", "Widen the IDENTITY column's declared type before its range is exhausted."),
 ];
}
